import React from 'react';
import { DollarSign, Users, ShoppingBag, TrendingUp, ArrowUp, ArrowDown } from 'lucide-react';

const StatsCards = () => {
  const stats = [
    { title: 'Revenu total', value: '$54,231', change: '+12.5%', icon: <DollarSign className="h-6 w-6" />, color: 'primary', trend: 'up' },
    { title: 'Nouveaux utilisateurs', value: '3,254', change: '+8.2%', icon: <Users className="h-6 w-6" />, color: 'accent', trend: 'up' },
    { title: 'Commandes', value: '1,243', change: '+5.7%', icon: <ShoppingBag className="h-6 w-6" />, color: 'secondary', trend: 'up' },
    { title: 'Taux de conversion', value: '3.42%', change: '-1.2%', icon: <TrendingUp className="h-6 w-6" />, color: 'warning', trend: 'down' },
  ];

  return (
    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-3 sm:gap-4 lg:gap-6 mb-6 sm:mb-8">
      {stats.map((stat, index) => (
        <div key={index} className="relative bg-gradient-to-br from-white to-white/70 dark:from-neutral-900 dark:to-neutral-900/70 backdrop-blur-xl rounded-xl sm:rounded-2xl p-4 sm:p-6 shadow-lg border border-white/30 dark:border-neutral-800/50 overflow-hidden group hover:scale-[1.02] transition-transform duration-300">
          <div className="relative z-10">
            <div className="flex items-center justify-between mb-3 sm:mb-4 gap-2">
              <div className={`p-2 sm:p-3 rounded-lg sm:rounded-xl bg-gradient-to-br from-${stat.color}-100 to-${stat.color}-50 dark:from-${stat.color}-900/30 dark:to-${stat.color}-800/20 flex-shrink-0`}>
                <div className={`text-${stat.color}-600 dark:text-${stat.color}-400 h-5 w-5 sm:h-6 sm:w-6`}>
                  {stat.icon}
                </div>
              </div>
              <div className={`flex items-center space-x-1 text-xs sm:text-sm font-medium flex-shrink-0 ${stat.trend === 'up' ? 'text-accent-500' : 'text-red-500'}`}>
                {stat.trend === 'up' ? <ArrowUp className="h-3 w-3 sm:h-4 sm:w-4" /> : <ArrowDown className="h-3 w-3 sm:h-4 sm:w-4" />}
                <span className="line-clamp-1">{stat.change}</span>
              </div>
            </div>
            <h3 className="text-lg sm:text-2xl font-bold text-neutral-900 dark:text-white mb-1 sm:mb-2">{stat.value}</h3>
            <p className="text-xs sm:text-sm text-neutral-600 dark:text-neutral-400 line-clamp-2">{stat.title}</p>
          </div>
        </div>
      ))}
    </div>
  );
};

export default StatsCards;
